<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Loan extends Model {protected $guarded=[]; protected function casts():array{return ['terms'=>'array','disbursed_at'=>'datetime','installation_date'=>'date','installation_confirmed_at'=>'datetime'];} public function customer(){return $this->belongsTo(User::class,'user_id');} public function financier(){return $this->belongsTo(Financier::class);} public function application(){return $this->belongsTo(LoanApplication::class,'application_id');} public function installments(){return $this->hasMany(Installment::class)->orderBy('number');} public function payments(){return $this->hasMany(Payment::class);} public function disbursement(){return $this->hasOne(Disbursement::class);} public function batchItem(){return $this->hasOne(DisbursementBatchItem::class);} public function payout(){return $this->hasOne(Payout::class);} public function outstanding():int{return (int)$this->installments()->selectRaw('COALESCE(SUM(principal + charge - paid_principal - paid_charge),0) AS balance')->value('balance');} public function pastDueAmount():int{return (int)$this->installments()->where('due_date','<',today())->selectRaw('COALESCE(SUM(principal+charge-paid_principal-paid_charge),0) AS total')->value('total');} public function pastDueDays():int{$due=$this->installments()->where('due_date','<',today())->whereRaw('principal+charge-paid_principal-paid_charge > 0')->min('due_date');return $due?\Carbon\Carbon::parse($due)->diffInDays(today()):0;}}
